function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const r=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('AlphaLab API '+r.status+': '+await r.text());return r.json()}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Pipeline preview requires an explicit user request and confirm_python_execution=true');const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const project=await get('/api/pipeline/projects/'+encodeURIComponent(id));const response=await fetch(origin()+'/api/pipeline/projects/'+encodeURIComponent(id)+'/preview',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({profile:input.profile==='runtime'?'runtime':'demo',...(input.as_of_date?{as_of_date:String(input.as_of_date)}:{})})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());const result=await response.json();if(result.source_sha256!==project.source_sha256)throw new Error('Pipeline source changed during preview');return{...result,project_preflight:{revision:project.revision,source_sha256:project.source_sha256,component_manifest:project.component_manifest}}}
